fn push<T>(values:&mut Vec<T>,value:T,control:&mut NativeEncodeControl<'_>)->Result<(),String>{if values.len()==values.capacity(){let capacity=if values.capacity()==0{1}else{values.capacity().checked_mul(2).ok_or("Pack output frontier capacity overflow")?};control.charge(capacity.checked_mul(size_of::<T>()).ok_or("Pack output frontier size overflow")?)?;control.checkpoint()?;values.try_reserve_exact(capacity-values.len()).map_err(|_|"Pack output frontier allocation")?;}values.push(value);Ok(())}
fn nested(shape:Option<&Shape>,control:&mut NativeEncodeControl<'_>)->Result<Option<RecordSpec>,String>{match shape{Some(Shape::Record(producer))=>producer.encode(control).map(Some),_=>Ok(None)}}

#[derive(Clone,Copy)]
struct Symbol<'a>{text:&'a str,forced:bool}
struct Symbols<'a>{entries:Vec<Symbol<'a>>}
impl<'a> Symbols<'a>{
    fn note(&mut self,text:&'a str,forced:bool,control:&mut NativeEncodeControl<'_>)->Result<(),String>{push(&mut self.entries,Symbol{text,forced},control)}
    fn record(&mut self,spec:Option<&RecordSpec>,record:&'a RecordValue,depth:u16,maximum:u16,control:&mut NativeEncodeControl<'_>)->Result<(),String>{
