    }
    fn value(&mut self,shape:Option<&Shape>,value:&'a FieldValue,depth:u16,maximum:u16,control:&mut NativeEncodeControl<'_>)->Result<(),String>{
        if depth>maximum.min(64){return Err("Pack symbol discovery depth exceeds limit".into())}control.scoped_stage(|control|{control.begin_stage(0)?;control.step()?;match value{
            FieldValue::Text(text)=>self.note(text,false,control)?,
            FieldValue::Tuple(items)=>{control.begin_stage(items.len())?;for item in items{self.value(elem_shape_of(shape),item,depth+1,maximum,control)?;control.step()?;}},
            FieldValue::List(items)=>{let table=table_spec_of(shape).map(|producer|producer.encode(control)).transpose()?;control.begin_stage(items.len())?;for item in items{if let(Some(spec),FieldValue::Record(row))=(&table,item){for field in &spec.fields{if let Some(value)=row.fields.get(&field.id){if matches!(field.shape,Shape::Text){if let FieldValue::Text(text)=value{self.note(text,true,control)?;}}else{self.value(Some(&field.shape),value,depth+1,maximum,control)?;}}}}else{self.value(elem_shape_of(shape),item,depth+1,maximum,control)?;}control.step()?;}},
            FieldValue::Record(record)=>{let spec=nested(shape,control)?;self.record(spec.as_ref(),record,depth+1,maximum,control)?;},
            FieldValue::Block(value)=>self.value(block_inner_shape(shape),value,depth+1,maximum,control)?,
            FieldValue::Statements(items)=>{control.begin_stage(items.len())?;for(keyword,record)in items{self.note(keyword,true,control)?;let spec=statements_variants(shape).and_then(|variants|variants.iter().find(|(key,_)|key==keyword)).map(|(_,producer)|producer.encode(control)).transpose()?;self.record(spec.as_ref(),record,depth+1,maximum,control)?;control.step()?;}},
            FieldValue::Map(items)=>{control.begin_stage(items.len())?;for(key,value)in items{self.note(key,false,control)?;self.value(map_inner_shape(shape),value,depth+1,maximum,control)?;control.step()?;}},
            FieldValue::Value(value)=>self.dynamic(value,depth+1,maximum,control)?,
            FieldValue::Wire(wire)=>{self.node(&wire.from,control)?;if let Some((_,node))=&wire.edge{self.node(node,control)?;}self.dynamic(&wire.properties,depth+1,maximum,control)?;},
            FieldValue::Absent|FieldValue::Bool(_)|FieldValue::Int(_)|FieldValue::UInt(_)|FieldValue::Float(_)|FieldValue::Bytes64(_)|FieldValue::Enum(_)|FieldValue::Expr(_)=>{},
        }Ok(())})
    }
    fn node(&mut self,node:&'a WireNode,control:&mut NativeEncodeControl<'_>)->Result<(),String>{self.note(&node.id,false,control)?;if let Some(text)=&node.kind{self.note(text,false,control)?;}if let Some(text)=&node.port{self.note(text,false,control)?;}Ok(())}
    fn dynamic(&mut self,value:&'a DslValue,depth:u16,maximum:u16,control:&mut NativeEncodeControl<'_>)->Result<(),String>{if depth>maximum.min(64){return Err("Pack dynamic symbol depth exceeds limit".into())}control.scoped_stage(|control|{control.begin_stage(0)?;control.step()?;match value{DslValue::String(text)=>self.note(text,false,control)?,DslValue::Array(items)=>{control.begin_stage(items.len())?;for item in items{self.dynamic(item,depth+1,maximum,control)?;control.step()?;}},DslValue::Object(items)=>{control.begin_stage(items.len())?;for(_,item)in items{self.dynamic(item,depth+1,maximum,control)?;control.step()?;}},DslValue::Null|DslValue::Bool(_)|DslValue::Number(_)|DslValue::Bytes(_)=>{}}Ok(())})}
    fn finish(&mut self,control:&mut NativeEncodeControl<'_>)->Result<(),String>{
        controlled_schema::sort(&mut self.entries,|a,b,control|controlled_schema::compare_text(a.text,b.text,control),control)?;
        control.scoped_stage(|control|{control.begin_stage(self.entries.len())?;let mut start=0;let mut output=0;while start<self.entries.len(){let text=self.entries[start].text;let mut end=start+1;let mut forced=self.entries[start].forced;control.step()?;while end<self.entries.len()&&controlled_schema::compare_text(text,self.entries[end].text,control)?==Ordering::Equal{forced|=self.entries[end].forced;end+=1;control.step()?;}if forced||text.len()<=128||end-start>=2{self.entries[output]=Symbol{text,forced};output+=1;}start=end;}self.entries.truncate(output);Ok(())})
    }
    fn index(&self,text:&str,control:&mut NativeEncodeControl<'_>)->Result<Option<u64>,String>{let mut low=0;let mut high=self.entries.len();while low<high{let middle=low+(high-low)/2;match controlled_schema::compare_text(self.entries[middle].text,text,control)?{Ordering::Less=>low=middle+1,Ordering::Greater=>high=middle,Ordering::Equal=>return Ok(Some(middle as u64))}}Ok(None)}
}

fn table_value(row:&FieldValue,id:u16)->Option<&FieldValue>{match row{FieldValue::Record(record)=>record.fields.get(&id).filter(|value|!matches!(value,FieldValue::Absent)),_=>None}}

struct Output{bytes:Option<Vec<u8>>,length:usize}
impl Output{
    fn measure()->Self{Self{bytes:None,length:0}}
    fn allocated(length:usize,control:&mut NativeEncodeControl<'_>)->Result<Self,String>{Ok(Self{bytes:Some(control.allocate_vec(length)?),length:0})}
    fn bytes(&mut self,bytes:&[u8],control:&mut NativeEncodeControl<'_>)->Result<(),String>{self.length=self.length.checked_add(bytes.len()).ok_or("Pack output length overflow")?;if let Some(output)=&mut self.bytes{if bytes.len()>output.capacity()-output.len(){return Err("Pack output exceeded admitted length".into())}control.scoped_stage(|control| -> ::core::result::Result<(),String> {control.begin_stage(bytes.len())?;for fragment in bytes.chunks(65536){output.extend_from_slice(fragment);control.advance(fragment.len())?;}Ok::<_,String>(())})?;}Ok(())}
    fn byte(&mut self,byte:u8,control:&mut NativeEncodeControl<'_>)->Result<(),String>{self.bytes(&[byte],control)}
    fn varint(&mut self,mut value:u64,control:&mut NativeEncodeControl<'_>)->Result<(),String>{let mut bytes=[0;10];let mut length=0;loop{bytes[length]=(value as u8)&127;value>>=7;if value!=0{bytes[length]|=128;}length+=1;if value==0{break;}}self.bytes(&bytes[..length],control)}
    fn signed(&mut self,value:i64,control:&mut NativeEncodeControl<'_>)->Result<(),String>{self.varint(((value as u64)<<1)^((value>>63)as u64),control)}
}

struct Encoder<'a,'b,'c,'d>{symbols:&'a Symbols<'b>,options:&'a EncodeOptions,control:&'c mut NativeEncodeControl<'d>,writer:Option<&'c mut crate::os_pack::format::ControlledPackWriter>,chunking:bool,next_chunk:u32}
impl Encoder<'_,'_,'_,'_>{
