    fn forced(&mut self,text:&str,output:&mut Output)->Result<(),String>{let index=self.symbols.index(text,self.control)?.ok_or("Pack forced symbol missing")?;output.varint(index,self.control)}
    fn fields(&mut self,spec:Option<&RecordSpec>,record:&RecordValue,depth:u16,output:&mut Output)->Result<(),String>{
