fn push<T,C:NativeSchemaControl>(values:&mut Vec<T>,value:T,control:&mut C)->Result<(),String>{
    if values.len()==values.capacity(){control.charge(size_of::<T>())?;values.try_reserve_exact(1).map_err(|_|"schema frontier allocation")?;}
    values.push(value);Ok(())
}
pub(super) fn compare_text<C:NativeSchemaControl>(a:&str,b:&str,control:&mut C)->Result<Ordering,String>{
    control.scoped_stage(|control|{let count=a.len().min(b.len());control.begin_stage(count)?;for offset in (0..count).step_by(65536){let end=(offset+65536).min(count);let order=a.as_bytes()[offset..end].cmp(&b.as_bytes()[offset..end]);control.advance(end-offset)?;if order!=Ordering::Equal{return Ok(order);}}Ok(a.len().cmp(&b.len()))})
}
pub(super) fn sort<T,C:NativeSchemaControl>(values:&mut[T],compare:impl Fn(&T,&T,&mut C)->Result<Ordering,String>,control:&mut C)->Result<(),String>{
    fn sift<T,C:NativeSchemaControl>(values:&mut[T],mut root:usize,end:usize,compare:&impl Fn(&T,&T,&mut C)->Result<Ordering,String>,control:&mut C)->Result<(),String>{
