}
fn edge<C:NativeSchemaControl>(producer:RecordSpecProducer,edges:&mut Vec<RecordSpecProducer>,control:&mut C)->Result<u32,String>{
    let index=u32::try_from(edges.len()).map_err(|_|"schema edge address exceeds u32")?;push(edges,producer,control)?;Ok(index)
