    control.scoped_stage(|control|{control.begin_stage(0)?;let mut nodes:Vec<(Vec<PackSchemaField>,Vec<usize>)>=Vec::new();let mut pending:Vec<RecordSpec>=Vec::new();let mut seen=HashMap::new();let mut cursor=0;
